import * as D from './domain-27ca4e179461.mjs';
import {weekStart,weeklyPlanSummary,weeklyCompletion,setWeeklyCompletion,compareWeek,saveWeeklyRule,saveWeeklyReview,reviewAdjustment,saveExample,exampleValue,personalBests} from './weekly-model-27ca4e179461.mjs';
const statuses={future:'未到',unknown:'暂无实录',pending:'有待确认范围','in-progress':'进行中',paused:'已暂停',ambiguous:'当地钟点有歧义，待核对','not-scheduled':'当时未登记安排',recorded:'已确认实录','not-done':'本人确认未做'};
const weekdays=['周一','周二','周三','周四','周五','周六','周日'];
const currentWeek=(s,ui)=>ui.weekStart??weekStart(D.dateKey(Date.now(),s.timeZone));
const rangeTitle=week=>week+' — '+D.addDays(week,6);
export function weeklyPlans(state,ui,{e,button,embedded=false}){
 const now=Date.now(),week=currentWeek(state,ui),todayWeek=weekStart(D.dateKey(now,state.timeZone));
 const details=v=>`${weekdays[v.weekday]} ${v.localStart} · ${v.durationMinutes}分钟${v.durationMinutes+Number(v.localStart.slice(0,2))*60+Number(v.localStart.slice(3))>=1440?' · 跨至次日':''} · ${e(state.activities.find(a=>a.id===v.activityId)?.name??'活动已归档')}`;
 return `<section class="card ${embedded?'weekly-embedded':''}" id="weekly-plans"><div class="section-title"><div>${embedded?'':'<h2>每周安排</h2>'}<p class="muted">预期位置与用时，不是实录。完成标记不增加实录或成长。</p></div>${button('new-weekly','＋ 新建安排','secondary')}</div><div class="section-title"><p>${week===todayWeek?'本周':week<todayWeek?'历史周':'所选周'}：${rangeTitle(week)}</p><div>${button('prev-week','‹ 上周','text-button')}${button('current-week','本周','text-button')}${button('next-week','下周 ›','text-button')}</div></div>${state.weeklyRules.map(r=>{
  const {selected:o,selectedVersion:v,currentVersion,upcoming,next}=weeklyPlanSummary(state,r,week,now),done=weeklyCompletion(state,o),canCheck=['scheduled','ambiguous'].includes(o.state)&&o.date<=D.dateKey(now,state.timeZone);
  const selected=o.state==='not-scheduled'?'<p class="muted">所选周未登记安排</p>':o.state==='paused'?`<p class="muted">所选周已暂停（自 ${v.effectiveFrom}）</p>`:`<p>所选周安排：${o.date} ${details(v)}</p>${o.state==='ambiguous'?'<p class="quiet-note">当地钟点有歧义，待核对</p>':''}`;
  const current=currentVersion&&currentVersion.id!==v?.id?`<p class="muted">${currentVersion.paused?'当前已暂停':'当前安排：'+details(currentVersion)}（自 ${currentVersion.effectiveFrom}）</p>`:'';
  const future=upcoming.map(({version,previous})=>`<p>已保存 · ${version.paused?'将于 '+version.effectiveFrom+' 暂停':previous?.paused?'将于 '+version.effectiveFrom+' 恢复：'+details(version):(previous?'调整':'')+'将于 '+version.effectiveFrom+' 生效：'+details(version)} ${button('view-week','查看该周','text-button',version.effectiveFrom)}</p>`).join('');
  const nextText=next?`${week===todayWeek?'下次':'从今天起的下次'}：${next.date} ${details(r.versions.find(v=>v.id===next.versionId))}${next.state==='ambiguous'?' · 当地钟点待核对':''}`:'暂未安排下一次';
  return `<div class="weekly-row"><div class="section-title"><h3>${e(r.title)}</h3>${button('edit-weekly','调整未来','text-button',r.id)}</div>${selected}${canCheck?`<button type="button" class="weekly-check ${done?'is-done':''}" data-action="week-check" data-id="${e(r.id)}" data-week="${week}" data-version="${e(o.versionId)}" data-completed="${!!done}" aria-pressed="${!!done}">${done?'✓ 已完成 · 撤销':'○ 标记这次完成'}</button>`:''}${current}${future}<p class="muted">${nextText}</p></div>`;
 }).join('')||'<p class="muted">想复看固定课表或生活规律时，再建一条。</p>'}${button('open-week-review','去所选周对照与复看 ›','text-button')}</section>`;
}
export function weeklyInsights(state,ui,{e,button,duration,num}){
 const week=currentWeek(state,ui),format=v=>v.minutes===null?statuses[v.status]:duration(v.minutes)+(v.status==='pending'?' · 部分待确认':''),reviews=state.weeklyReviews.filter(r=>!r.notDone&&r.weekStart<=week),groups=personalBests(state);
 return `<section class="card" id="weekly-insights"><div class="section-title"><h2>每周对照与一次改进</h2><div>${button('prev-week','‹ 上周','text-button')}${button('current-week','本周','text-button')}${button('next-week','下周 ›','text-button')}</div></div><p>${rangeTitle(week)} · ${e(state.timeZone)}</p><p class="quiet-note">自动读取已确认记录；安排和提醒不增加实际时间。</p>${state.weeklyRules.map(rule=>{const v=compareWeek(state,rule,week);return `<article class="weekly-row"><div class="section-title"><h3>${e(rule.title)}</h3>${button('week-adjust','留一次调整','text-button',rule.id)}</div><div class="week-comparison"><div><small>上周${v.previous.fallback?' · 按本周同钟点查旧实录':''}</small><p>${e(v.previous.localStart??'—')} · ${v.previous.durationMinutes??'—'}分钟窗口</p><strong>${format(v.previous)}</strong></div><div><small>本周</small><p>${e(v.current.localStart??'—')} · ${v.current.durationMinutes??'—'}分钟窗口</p><strong>${format(v.current)}</strong></div></div><p class="quiet-note">${v.comparable?'窗口内实录差：'+(v.difference>=0?'＋':'')+num(v.difference)+'分钟；不直接说明效率或原因。':'两侧须已结束且活动、窗口长度可比，才显示差值。'}${v.previous.fallback?' 上周没有登记安排。':''}</p><details><summary>实际来源与安排</summary>${v.current.rows.map(r=>button('session',e(r.name)+' · '+duration((r.end-r.start)/60000),'text-button',r.id)).join('')||'<p>没有可列的已确认实际。</p>'}${button('edit-weekly','改未来安排','secondary',rule.id)}${v.current.status==='unknown'?button('week-not-done','这次确定未做','text-button',rule.id):''}</details></article>`;}).join('')||`<p class="muted">还没有固定安排，可以先正常记录。</p><button type="button" class="secondary" data-nav="plans">去阶段建立每周安排</button>`}${reviews.length?`<details open><summary>调整与后续复看</summary>${reviews.map(r=>{const rule=state.weeklyRules.find(x=>x.id===r.slotId),actual=rule?compareWeek(state,rule,r.weekStart):null,changed=actual&&(actual.current.minutes!==r.snapshot?.current||actual.previous.minutes!==r.snapshot?.previous);return `<div class="weekly-row"><h3>${e(r.adjustment||'这周的复看')}</h3><p>${r.weekStart} · ${e(rule?.title??'原安排')}</p>${r.expectation?`<p>当时预期：${e(r.expectation)}</p>`:''}<p>${r.status==='pending'?'下周复看，允许资料不足':e({continue:'继续',adjust:'再调',stop:'停止',insufficient:'资料不足'}[r.status])}${r.conclusion?' · '+e(r.conclusion):''}</p>${changed?'<p class="quiet-note">依据的实录已有更正；原预期与心得保留。</p>':''}${D.addDays(r.weekStart,7)<=week?button('review-adjustment','留下这次复看','secondary',r.id):''}<details><summary>原判断与后续记录</summary><p>保存于 ${D.dateKey(r.at,state.timeZone)}</p>${(r.decisions??[]).map(d=>`<p>${D.dateKey(d.at,state.timeZone)} · ${e(d.conclusion||d.status)}</p>`).join('')}</details></div>`;}).join('')}</details>`:''}</section>
 <section class="card" id="personal-bests"><h2>留过的表现</h2><p class="quiet-note">从已结束的活动选择“留这次表现”。量化速率按整次用时计算，状态与心得单独保留。</p>${groups.map(g=>{const first=g.all[0].example;return `<div class="weekly-row"><h3>${e(state.activities.find(a=>a.id===first.activityId)?.name??'原活动')} · ${e(first.standard)}</h3><p>${g.highest.length?(g.highest.length>1?'已记录并列最高':'已记录最高')+'：'+num(g.highest[0].rate)+' '+e(first.unit)+'/小时':g.sampleCount===1?'目前1次可比记录':g.sampleCount?'目前均为已确认0量':'尚无可比记录'} · 有效样本 ${g.sampleCount} 次</p>${g.all.map(v=>`<p>${D.dateKey(v.example.at,state.timeZone)} · ${v.valid&&v.rate!==null?num(v.example.quantity)+' '+e(v.example.unit)+' / '+duration(v.duration/60000)+' = '+num(v.rate)+' /小时':v.example.needsReview?'来源已变，需核对':'量或时间资料不足'} ${button('edit-example',v.example.needsReview?'核对来源':'查看／修改','text-button',v.example.id)}</p>${v.example.note?`<p class="muted">${e(v.example.note)}</p>`:''}`).join('')}</div>`;}).join('')}${state.eventExamples.filter(x=>x.kind==='subjective').map(x=>`<div class="weekly-row"><h3>主观好状态 · ${D.dateKey(x.at,state.timeZone)}</h3><p>${e(x.note)}</p>${x.needsReview?'<p class="quiet-note">时间来源已变，心得仍保留。</p>':''}${button('edit-example','查看／修改','text-button',x.id)}</div>`).join('')}${!state.eventExamples.length?'<p class="muted">还没有留存表现。只有时间长短不称为效率高低。</p>':''}</section>`;
}
export function createWeeklyUI({getState,getUI,tasks,e,save,navigate,render,toast}){
 async function editRule(id=null){const s=getState(),r=s.weeklyRules.find(r=>r.id===id),week=weekStart(D.dateKey(Date.now(),s.timeZone)),v=r?.versions.at(-1),initial={title:r?.title??'',activityId:v?.activityId??s.activities.find(a=>!a.archived)?.id,weekday:v?.weekday??0,localStart:v?.localStart??'09:00',durationMinutes:v?.durationMinutes??60,effectiveFrom:D.addDays(week,7),paused:v?.paused?['on']:[]};
  await tasks.open({id:'weekly:'+(id??'new'),kind:'weekly',title:id?'调整未来的周安排':'每周固定的一件事',initial,original:r??null,body:values=>`<label>安排名称 · 选填<input name="title" maxlength="100"></label><label>活动<select name="activityId">${s.activities.filter(a=>!a.archived||a.id===values.activityId).map(a=>`<option value="${e(a.id)}">${e(a.category)} · ${e(a.name)}${a.archived?' · 已归档，请重新选择':''}</option>`).join('')}</select></label><div class="form-row"><label>星期<select name="weekday">${weekdays.map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></label><label>开始钟点<input type="time" name="localStart" required></label></div><label>安排时长（分钟，跨夜会明确显示）<input type="number" name="durationMinutes" min="1" max="1440" required></label><label>从哪周生效<select name="effectiveFrom"><option value="${week}">本周尚未发生的一次</option><option value="${D.addDays(week,7)}">下周 ${D.addDays(week,7)}</option><option value="${D.addDays(week,14)}">再下一周 ${D.addDays(week,14)}</option></select></label><label class="check"><input type="checkbox" name="paused">从所选周暂停，历史保持</label><p class="quiet-note" data-week-window></p>`,bind(form){const sync=()=>{const start=form.elements.localStart.value,m=Number(start.slice(0,2))*60+Number(start.slice(3))+Number(form.elements.durationMinutes.value);form.querySelector('[data-week-window]').textContent='结束在'+(m>=1440?'次日 ':'当日 ')+String(Math.floor(m%1440/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')+'；使用账本时区 '+s.timeZone;};form.addEventListener('input',sync);sync();},onSave:async(f,{commit,original})=>{await commit(state=>{if(id&&JSON.stringify(state.weeklyRules.find(x=>x.id===id))!==JSON.stringify(original))throw Error('安排已在其他页面修改，草稿保留');return saveWeeklyRule(state,{id,title:String(f.get('title')).trim()||state.activities.find(a=>a.id===f.get('activityId')).name,activityId:f.get('activityId'),weekday:Number(f.get('weekday')),localStart:f.get('localStart'),durationMinutes:Number(f.get('durationMinutes')),effectiveFrom:f.get('effectiveFrom'),paused:f.has('paused')});});}});
 }
 async function adjust(id){const s=getState(),week=currentWeek(s,getUI()),rule=s.weeklyRules.find(r=>r.id===id);if(!rule)return;await tasks.open({id:'review:'+id+':'+week,kind:'review',title:'下周只试一处调整',initial:{adjustment:'',expectation:''},body:()=>`<p>${e(rule.title)} · ${rangeTitle(week)}</p><label>想试什么<input name="adjustment" maxlength="2000" required placeholder="例如：开始前先挑四道同类题"></label><label>希望观察什么 · 选填<textarea name="expectation" maxlength="2000"></textarea></label><p class="quiet-note">这是一条待复看的想法，不会自动改课表或补记时间。</p>`,onSave:async(f,{commit})=>commit(state=>saveWeeklyReview(state,{slotId:id,week,adjustment:f.get('adjustment'),expectation:f.get('expectation')}))});}
 async function review(id){const r=getState().weeklyReviews.find(r=>r.id===id);if(!r)return;await tasks.open({id:'review-result:'+id,kind:'review',title:'这次复看',initial:{status:r.status==='pending'?'insufficient':r.status,conclusion:''},body:()=>`<p>${e(r.adjustment)}</p><label>接下来<select name="status"><option value="continue">继续沿用</option><option value="adjust">再调整</option><option value="stop">停止这次尝试</option><option value="insufficient">资料不足</option></select></label><label>结果、条件或体验 · 选填<textarea name="conclusion" maxlength="2000"></textarea></label>`,onSave:async(f,{commit})=>commit(s=>reviewAdjustment(s,id,f.get('status'),f.get('conclusion')))});}
 async function example(sessionId=null,id=null){const s=getState(),existing=s.eventExamples.find(x=>x.id===id),row=s.sessions.find(r=>r.id===(existing?.sessionId??sessionId)&&r.confirmation!=='pending'),last=s.eventExamples.findLast(x=>x.activityId===row?.activityId&&x.kind==='quantitative');if(!row&&!existing)throw Error('请选择已结束、已确认的活动');
  await tasks.open({id:'example:'+(id??sessionId),kind:'example',title:existing?.needsReview?'核对这次表现的完整来源':'留这次表现',original:existing??null,initial:existing??{sessionId,kind:'quantitative',unit:last?.unit??'',standard:last?.standard??'',quantity:'',note:''},body:()=>`<label>完整事件<select name="sessionId">${s.sessions.filter(r=>r.confirmation!=='pending').sort((a,b)=>b.start-a.start).filter((r,i)=>i<200||r.id===(existing?.sessionId??sessionId)).map(r=>`<option value="${e(r.id)}">${D.dateKey(r.start,s.timeZone)} · ${e(r.name)} · ${Math.round((r.end-r.start)/60000*100)/100}分钟</option>`).join('')}</select></label><label>留存方式<select name="kind"><option value="quantitative">量化完成表现</option><option value="subjective">主观状态最好／心得</option></select></label><section data-quantity-fields><label>完成量 · 留空表示未知<input type="number" name="quantity" min="0" step="any"></label><div class="form-row"><label>单位<input name="unit" maxlength="40" placeholder="题、页、件"></label><label>完成标准<input name="standard" maxlength="300" placeholder="例如：首次独立做对的同类题"></label></div></section><label>条件与心得<textarea name="note" maxlength="5000"></textarea></label><label class="check"><input type="checkbox" name="whole" required>所选时间仍是这一次完整事件；填量时，数量对应全段</label><p class="quiet-note">不同活动、单位或完成标准分别比较。主观状态不参与量化排序。</p>`,bind(form){const sync=()=>{const quantitative=form.elements.kind.value==='quantitative';form.querySelector('[data-quantity-fields]').hidden=!quantitative;for(const field of form.querySelector('[data-quantity-fields]').querySelectorAll('input'))field.disabled=!quantitative;form.elements.unit.required=quantitative;form.elements.standard.required=quantitative;};form.elements.kind.onchange=sync;sync();},onSave:async(f,{commit,original})=>commit(state=>{if(id&&JSON.stringify(state.eventExamples.find(x=>x.id===id))!==JSON.stringify(original))throw Error('表现记录已变化，请重新核对');return saveExample(state,{id,sessionId:f.get('sessionId'),kind:f.get('kind'),quantity:f.get('quantity')===''?null:Number(f.get('quantity')),unit:String(f.get('unit')),standard:String(f.get('standard')),note:String(f.get('note'))});})});
 }
 return {resume:async d=>{if(d.kind==='weekly')return editRule(d.id==='weekly:new'?null:d.id.slice(7));if(d.kind==='example')return d.payload.original?example(null,d.payload.original.id):example(d.id.slice(8));if(d.id.startsWith('review-result:'))return review(d.id.slice(14));const tail=d.id.slice(7),week=tail.slice(-10),id=tail.slice(0,-11);getUI().weekStart=week;return adjust(id);},actions:{'week-check':async(id,el)=>{const completed=el.dataset.completed!=='true',week=el.dataset.week,versionId=el.dataset.version;await save(s=>setWeeklyCompletion(s,{ruleId:id,week,versionId,completed}));toast(completed?'这次已标记完成':'已撤销这次完成');},'new-weekly':()=>editRule(),'edit-weekly':editRule,'open-week-review':()=>navigate('iteration',{navPage:'iteration',weekStart:currentWeek(getState(),getUI()),revealTarget:'#weekly-insights'}),'view-week':week=>{if(D.isDate(week)&&weekStart(week)===week){getUI().weekStart=week;render();}},'prev-week':()=>{getUI().weekStart=D.addDays(currentWeek(getState(),getUI()),-7);render();},'next-week':()=>{getUI().weekStart=D.addDays(currentWeek(getState(),getUI()),7);render();},'current-week':()=>{getUI().weekStart=weekStart(D.dateKey(Date.now(),getState().timeZone));render();},'week-adjust':adjust,'review-adjustment':review,'week-not-done':async id=>{await save(s=>saveWeeklyReview(s,{slotId:id,week:currentWeek(s,getUI()),notDone:true}));toast('已保留你对这次未做的确认');},'leave-example':id=>example(id),'edit-example':id=>example(null,id)}};
}
